public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    if (nums == null) return res;
    int n = nums.length;
    boolean[] used = new boolean[n];
    List<Integer> current = new ArrayList<>();
    backtrack(nums, used, current, res);
    return res;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> res) {
    if (current.size() == nums.length) {
        res.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true;
        current.add(nums[i]);
        backtrack(nums, used, current, res);
        current.remove(current.size() - 1);
        used[i] = false;
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Filter out null strings and find maximum length
    int maxLen = 0;
    for (String s : strings) {
        if (s == null) {
            continue;
        }
        if (s.length() > maxLen) {
            maxLen = s.length();
        }
    }
    if (maxLen == 0) {
        return 0;
    }

    // Use the first non-null string as reference for candidate substrings
    String reference = null;
    for (String s : strings) {
        if (s != null) {
            reference = s;
            break;
        }
    }
    if (reference == null) {
        return 0;
    }

    // Iterate lengths from longest to shortest
    for (int len = maxLen; len >= 1; len--) {
        Set<String> candidates = new HashSet<>();
        // Generate all substrings of length len from reference
        for (int i = 0; i <= reference.length() - len; i++) {
            candidates.add(reference.substring(i, i + len));
        }

        // Check each candidate
        for (String cand : candidates) {
            String rev = new StringBuilder(cand).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (s == null) {
                    ok = false;
                    break;
                }
                if (!(s.contains(cand) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int deposits = 0;
    int[] dRow = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dCol = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                deposits++;
                // BFS to mark all connected '@'
                java.util.ArrayDeque<int[]> queue = new java.util.ArrayDeque<>();
                queue.add(new int[]{r, c});
                visited[r][c] = true;
                while (!queue.isEmpty()) {
                    int[] pos = queue.poll();
                    int curR = pos[0];
                    int curC = pos[1];
                    for (int dir = 0; dir < 8; dir++) {
                        int nr = curR + dRow[dir];
                        int nc = curC + dCol[dir];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                                && grid[nr][nc] == '@' && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            queue.add(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }
    return deposits;
}

