public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || start.length != n || end.length != n) {
        return "cannot be travelled";
    }
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    java.util.function.Function<int[], String> keyFunc = coord -> java.util.Arrays.toString(coord);
    String startKey = keyFunc.apply(start);
    String endKey = keyFunc.apply(end);
    graph.putIfAbsent(startKey, new java.util.ArrayList<>());
    graph.putIfAbsent(endKey, new java.util.ArrayList<>());
    for (int[] path : paths) {
        if (path == null || path.length != 2 * n) {
            continue;
        }
        int[] a = java.util.Arrays.copyOfRange(path, 0, n);
        int[] b = java.util.Arrays.copyOfRange(path, n, 2 * n);
        String aKey = keyFunc.apply(a);
        String bKey = keyFunc.apply(b);
        graph.putIfAbsent(aKey, new java.util.ArrayList<>());
        graph.putIfAbsent(bKey, new java.util.ArrayList<>());
        graph.get(aKey).add(bKey);
        graph.get(bKey).add(aKey);
    }
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String cur = queue.poll();
        if (cur.equals(endKey)) {
            return "can be travelled";
        }
        for (String neigh : graph.getOrDefault(cur, java.util.Collections.emptyList())) {
            if (!visited.contains(neigh)) {
                visited.add(neigh);
                queue.add(neigh);
            }
        }
    }
    return "cannot be travelled";
}

