        java.time.format.TextStyle style = java.time.format.TextStyle.FULL;
        java.util.Locale locale = java.util.Locale.ENGLISH;

        String monthName = localDate.getMonth().getDisplayName(style, locale);
        String weekdayName = localDate.getDayOfWeek().getDisplayName(style, locale);
