public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }
    int[] count = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        count[r]++;
    }
    // Remainder 0 must be even
    if (count[0] % 2 != 0) {
        return false;
    }
    // If k is even, remainder k/2 must also be even
    if (k % 2 == 0 && count[k / 2] % 2 != 0) {
        return false;
    }
    // For other remainders, counts must match complementary remainders
    for (int r = 1; r < k; r++) {
        if (r == k - r) {
            continue; // already handled for even k
        }
        if (count[r] != count[k - r]) {
            return false;
        }
    }
    return true;
}

