public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] freq = new int[256];
    for (char ch : s.toCharArray()) {
        freq[ch]++;
    }
    StringBuilder sb = new StringBuilder();
    int total = s.length();
    while (sb.length() < total) {
        for (int i = 0; i < 256; i++) {
            if (freq[i] > 0) {
                sb.append((char) i);
                freq[i]--;
            }
        }
        for (int i = 255; i >= 0; i--) {
            if (freq[i] > 0) {
                sb.append((char) i);
                freq[i]--;
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // dp[k][s] == true if a subset of size k with sum s exists
    boolean[][] dp = new boolean[n + 1][totalSum + 1];
    dp[0][0] = true;
    for (int num : nums) {
        // iterate k in reverse to avoid using the same element twice
        for (int k = n - 1; k >= 0; k--) {
            for (int s = 0; s <= totalSum - num; s++) {
                if (dp[k][s]) {
                    dp[k + 1][s + num] = true;
                }
            }
        }
    }
    for (int k = 1; k < n; k++) {
        if ((totalSum * k) % n != 0) {
            continue;
        }
        int target = (totalSum * k) / n;
        if (dp[k][target]) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int uniqueMorseRepresentations(String[] words) {
