    String[] morse = {".-","-...","-.-.","-..",".","..-.","--.","....","..",
                      ".---","-.-",".-..","--","-.","---",".--.","--.-",".-.",
                      "...","-","..-","...-",".--","-..-","-.--","--.."};
    Set<String> unique = new HashSet<>();
    for (String word : words) {
        if (word == null) {
            continue;
        }
        StringBuilder sb = new StringBuilder();
        for (char c : word.toCharArray()) {
            if (c >= 'a' && c <= 'z') {
                sb.append(morse[c - 'a']);
            } else if (c >= 'A' && c <= 'Z') {
                sb.append(morse[c - 'A']);
            } // ignore non-letter characters
        }
        unique.add(sb.toString());
    }
    return unique.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    int totalCodes = 1 << k;
    if (totalCodes > n) {
        // Quick check: if the string is shorter than the number of possible codes, impossible
        // (though this is not a strict requirement, it can short‑circuit some cases)
    }
    boolean[] seen = new boolean[totalCodes];
    int seenCount = 0;
    int mask = totalCodes - 1;
    int current = 0;
    for (int i = 0; i < n; i++) {
        current = ((current << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[current]) {
                seen[current] = true;
                seenCount++;
                if (seenCount == totalCodes) {
                    return true;
                }
            }
        }
    }
    return false;
}

